module Mcp
  module Tools
    # The app's own MCP tools (generated by maquina:mcp). `rails g
    # maquina:mcp_tool NAME` adds to this file at the three maquina:mcp_tool
    # markers; leave them in place and edit everything else freely.
    #
    # A tool is a DEFINITIONS entry, which is what the model reads, plus a
    # `def self.<name>(scope:, **arguments)` that returns a Hash. Reach records
    # only through scope (an Mcp::UserScope): scope.records(:posts),
    # scope.find(:posts, id). Raise Mcp::ToolError with a message for the
    # model when a call cannot be done. A tool that changes data has
    # readOnlyHint: false and its name in WRITE_TOOLS.
    module App
      ADMIN_ONLY = false

      DEFINITIONS = [
        {
          name: "whoami",
          description: "Shows who this connection acts as. Returns the signed-in user's email address, " \
            "the OAuth scopes this connection was granted (read, or read write), the server version and " \
            "the MCP protocol revision. Takes no arguments. Call it to check that the connection works.",
          inputSchema: {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            type: "object",
            properties: {},
            required: [],
            additionalProperties: false
          },
          annotations: {readOnlyHint: true}
        }
        # maquina:mcp_tool definitions go above this line
      ].freeze

      # maquina:mcp_tool write tools are listed on the next line
      WRITE_TOOLS = %w[].freeze

      def self.whoami(scope:)
        result = {
          email: scope.user.email_address,
          scope: scope.oauth_scopes.join(" "),
          server_version: Mcp::SERVER_VERSION,
          protocol_version: Mcp::PROTOCOL_VERSION
        }
        result[:flag] = {name: Mcp::FLAG.to_s, enabled: scope.enabled?} if Mcp::FLAG
        result
      end

      # maquina:mcp_tool methods go above this line
    end
  end
end
